        lines: ['satis = [10, 20, 30, 40, 50]', 'orta = len(satis) // 2', 'parcalar = [satis[:orta], satis[orta:]]', 'kismi = list(map(sum, parcalar))', 'print(kismi, sum(kismi))'],
        expect: '[30, 120] 150\n',
