        sol: 'import veri\n\nSIP = """WITH sip AS (\n    SELECT o.order_id, o.customer_id, o.order_date, o.channel,\n           SUM(oi.quantity * oi.unit_price * (1 - oi.discount)) AS tutar\n    FROM orders o JOIN order_items oi ON oi.order_id = o.order_id\n    WHERE o.status = \'delivered\'\n    GROUP BY o.order_id\n)"""\n\ndef aylik_buyume(con, yil):\n    sql = SIP + """,\n    aylik AS (\n        SELECT substr(order_date, 1, 7) AS ay, ROUND(SUM(tutar), 2) AS ciro\n        FROM sip WHERE substr(order_date, 1, 4) = ?\n        GROUP BY ay\n    )\n    SELECT ay, ciro,\n           ROUND(100.0 * (ciro - LAG(ciro) OVER (ORDER BY ay)) / LAG(ciro) OVER (ORDER BY ay), 1)\n    FROM aylik ORDER BY ay\n    """\n    return con.execute(sql, (str(yil),)).fetchall()\n',
